WITH deduped AS (SELECT * FROM (SELECT *, ROW_NUMBER() OVER (PARTITION BY method ORDER BY paid_at NULLS LAST, id) AS rn FROM payments) t WHERE rn = 1) SELECT DATE_TRUNC('YEAR', paid_at) AS year_start, method, APPROX_PERCENTILE(amount, 0.5) AS amount_p50, COUNT(CASE WHEN method = 'paypal' THEN 1 END) AS paypal_count, (UNIX_TIMESTAMP(MAX(paid_at)) - UNIX_TIMESTAMP(MIN(paid_at))) / 60 AS duration_min, MAX(paid_at) AS last_paid_at, APPROX_PERCENTILE(amount, 0.9) AS amount_p90, GROUPING_ID() AS grouping_id FROM deduped GROUP BY GROUPING SETS ((DATE_TRUNC('YEAR', paid_at), method), (DATE_TRUNC('YEAR', paid_at)), ()) ORDER BY amount_p90 DESC NULLS FIRST
